 * Parse a build graph from raw input text.
 *
 * Returns `{ tasks, depsMap }` where `tasks` maps task name to its cost and
 * `depsMap` maps task name to the set of names it depends on (deduplicated,
 * with self and forward references allowed since `dep` lines may precede
 * the `task` lines they name).
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const depLines = []

  lines.forEach((rawLine, index) => {
    const lineNo = index + 1
    const trimmed = rawLine.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) fail(`line ${lineNo}: expected task <name> <cost>`)
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) fail(`line ${lineNo}: invalid task name ${name}`)
      if (!COST_RE.test(costStr)) fail(`line ${lineNo}: cost must be a non-negative integer`)
      if (tasks.has(name)) fail(`line ${lineNo}: task ${name} is declared twice`)
      tasks.set(name, Number(costStr))
    } else if (directive === 'dep') {
      if (words.length < 3) fail(`line ${lineNo}: expected dep <name> <dependency>...`)
      const [, name, ...deps] = words
      depLines.push({ name, deps })
    } else {
      fail(`line ${lineNo}: unknown directive ${directive}`)
    }
  })

  const depsMap = new Map()
  for (const { name, deps } of depLines) {
    for (const used of [name, ...deps]) {
      if (!tasks.has(used)) fail(`unknown task ${used}`)
    }
    if (!depsMap.has(name)) depsMap.set(name, new Set())
    const set = depsMap.get(name)
    for (const dep of deps) set.add(dep)
  }

  return { tasks, depsMap }
}
"}

