/**
 * Find the first cycle a depth-first search reaches when it starts from
 * each task in ascending name order and walks each task's dependencies in
 * ascending name order. Returns the cycle as an array of names, starting
 * and ending with the re-entered task, or null when the graph is acyclic.
 */
export function findCycle(names, depsMap) {
  const done = new Set()
  const stack = []
  const stackIndex = new Map()

  function visit(node) {
    if (stackIndex.has(node)) return stack.slice(stackIndex.get(node)).concat(node)
    if (done.has(node)) return null

    stack.push(node)
    stackIndex.set(node, stack.length - 1)

    const deps = [...(depsMap.get(node) || [])].sort()
    for (const dep of deps) {
      const found = visit(dep)
      if (found) return found
    }

    stack.pop()
    stackIndex.delete(node)
    done.add(node)
    return null
  }

  for (const name of names) {
    if (!done.has(name)) {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}

/** Throw the specified cycle error, exit code 3, when the graph has a cycle. */
export function checkForCycle(names, depsMap) {
  const cycle = findCycle(names, depsMap)
  if (cycle) fail(`cycle: ${cycle.join(' -> ')}`, 3)
}
"}

