{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-8bJ9oW/src/schedule.js","content":"/**
 * Compute the unlimited-worker schedule: each task's start, finish and
 * wave depth. A task's start is the greatest finish of its dependencies,
 * or 0 when it has none; its finish is its start plus its cost. Its depth
 * is 0 when it has no dependency, or one more than the deepest dependency.
 */
export function computeSchedule(tasks, depsMap) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function computeFinish(name) {
    if (finish.has(name)) return finish.get(name)
    const deps = [...(depsMap.get(name) || [])]
    const s = deps.length === 0 ? 0 : Math.max(...deps.map(computeFinish))
    const f = s + tasks.get(name)
    start.set(name, s)
    finish.set(name, f)
    return f
  }

  function computeDepth(name) {
    if (depth.has(name)) return depth.get(name)
    const deps = [...(depsMap.get(name) || [])]
    const d = deps.length === 0 ? 0 : 1 + Math.max(...deps.map(computeDepth))
    depth.set(name, d)
    return d
  }

  for (const name of tasks.keys()) {
    computeFinish(name)
    computeDepth(name)
  }

  const total = tasks.size === 0 ? 0 : Math.max(...finish.values())
  return { start, finish, depth, total }
}
"}

