 * A task's priority for packing is the cost of the longest chain that
 * begins at it: its own cost, plus the priority of whichever task that
 * depends on it continues the longest chain, down to a task nothing
 * depends on.
 */
function computePriority(tasks, depsMap) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, deps] of depsMap) {
    for (const dep of deps) dependents.get(dep).push(name)
  }

  const priority = new Map()
  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    const forward = dependents.get(name)
    const best = forward.length === 0 ? 0 : Math.max(...forward.map(compute))
    const p = tasks.get(name) + best
    priority.set(name, p)
    return p
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}

/**
 * Simulate the graph on the given number of workers with greedy priority
 * scheduling: while a worker is free and some task is ready, start the
 * ready task with the greatest priority (ties by ascending name) on the
 * free worker with the smallest index; otherwise advance time to the next
