  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) fail('workers must be a positive integer')
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  fail(USAGE)
