  const byDepth = new Map()
  for (const name of names) {
    const d = schedule.depth.get(name)
    if (!byDepth.has(d)) byDepth.set(d, [])
    byDepth.get(d).push(name)
  }
  const maxDepth = names.length === 0 ? -1 : Math.max(...byDepth.keys())
  const lines = []
  for (let k = 0; k <= maxDepth; k++) {
    const group = (byDepth.get(k) || []).sort()
    lines.push(`wave ${k}: ${group.join(' ')}`)
  }
  lines.push(`total ${schedule.total}`)
  return lines.join('\n') + '\n'
}

function renderExplain(names, schedule) {
  const lines = names
    .slice()
    .sort()
    .map((name) => `${name} start=${schedule.start.get(name)} finish=${schedule.finish.get(name)} depth=${schedule.depth.get(name)}`)
  lines.push(`total ${schedule.total}`)
  return lines.join('\n') + '\n'
}

