  const lines = []
  for (let i = 0; i < workerCount; i++) {
    const tasks = result.workerLog[i]
    const rendered = tasks.map((t) => `${t.name}@${t.start}-${t.finish}`)
    lines.push(rendered.length === 0 ? `worker ${i}:` : `worker ${i}: ${rendered.join(' ')}`)
  }
  lines.push(`makespan ${result.makespan}`)
  return lines.join('\n') + '\n'
